"""Foundation resource triggers (owner 2026-09-28: "automate every aspect"): Golden Sea Pulse is generated by hostile
pressure and expires at the end of its holder's next turn; Saint-Body Frame's once-a-round bonus. combat/pressure.py."""

from pathlib import Path

from combat import pressure
from combat.factory_compiler import compile_character
from combat.gate2_runtime_content import AN
from combat.gate4_engine import Gate4ControllerEngine
from tests.test_zones import SHEET

ROOT = Path(__file__).resolve().parents[1]
ME = "actor:factory.saint"
PULSE = "resource:foundation.golden_sea_pulse"
FOUNDATION = {"foundation_id": "ancient_desolate_sacred_body_v0_2C", "stage": "Awakened",
              "resource": {"name": "Golden Sea Pulse", "resource_id": "foundation.resource.ancient_desolate_sacred_body_v0_2C",
                           "maximum": 1, "current": 0, "initial_current": 0}}


def _engine():
    bundle = compile_character({**SHEET, "foundation": FOUNDATION}, actor_id=ME)
    engine = Gate4ControllerEngine(ROOT, match_seed="PULSE", typed_bundles=(bundle,),
                                   roster_setup={"primary_actor_ids": [ME, AN], "team_by_actor": {ME: "team:a", AN: "team:b"},
                                                 "starting_positions": {ME: {"x": 3, "y": 6}, AN: {"x": 4, "y": 6}}})
    engine.state.current_slot_index = engine.state.initiative_order.index(AN)
    engine.state.current_actor_id = AN
    return engine, bundle


def test_the_foundation_rows_compile():
    _engine_, bundle = _engine()
    blocks = {row["block"] for row in bundle["typed_passives"] if row.get("feature_id", "").startswith("foundation.ancient_desolate")}
    assert {"generate", "save_bonus"} <= blocks
    assert "Generate Golden Sea Pulse" not in bundle["diagnostics"]["skipped"]["passive"]


def test_hostile_damage_generates_one_pulse_once_a_round_and_it_expires_after_the_next_turn():
    engine, _bundle = _engine()
    me, foe = engine.state.actors[ME], engine.state.actors[AN]
    assert me.resources[PULSE] == 0
    engine._append_event("DAMAGE_COMMITTED", "test", actor_id=AN, target_ids=(ME,), payload={"hp_damage": 3, "temporary_hp_absorbed": 0})
    assert me.resources[PULSE] == 1
    engine._spend_resource(me, PULSE, 1, "test")  # spent (Golden Sea Guard)
    engine._append_event("DAMAGE_COMMITTED", "test", actor_id=AN, target_ids=(ME,), payload={"hp_damage": 3, "temporary_hp_absorbed": 0})
    assert me.resources[PULSE] == 0  # once a round
    engine.state.round_number += 1
    engine._append_event("DAMAGE_COMMITTED", "test", actor_id=AN, target_ids=(ME,), payload={"hp_damage": 2, "temporary_hp_absorbed": 0})
    assert me.resources[PULSE] == 1
    engine._append_event("TURN_ENDED", "test", actor_id=ME, payload={})  # gained on the foe's turn: gone after its own next turn
    assert me.resources[PULSE] == 0
    del foe


def test_saint_body_frame_adds_pb_once_a_round_against_body_pressure():
    engine, _bundle = _engine()
    me = engine.state.actors[ME]
    bonus, feature = pressure.save_bonus(engine, me, "STR", {"prone"})
    assert bonus >= 2 and feature.endswith("saint_body_frame")
    assert pressure.save_bonus(engine, me, "CON", {"forced_movement"}) == (0, None)  # once a round
    engine.state.round_number += 1
    assert pressure.save_bonus(engine, me, "WIS", {"frightened"}) == (0, None)  # not the body
